export const FOLDER_ICON = ICONS["folder"]!;
export const FOLDER_OPEN_ICON = ICONS["folder-open"]!;

/**
 * The pack's icon id for a file name or path, matched as VS Code does: the exact
 * name first, then the longest extension (`a.d.ts` tries `d.ts` before `ts`).
 */
export function fileIconId(name: string): string {
  const base = name.slice(name.lastIndexOf("/") + 1).toLowerCase();
  const exact = ICON_BY_NAME[base];
  if (exact) return exact;
  for (let dot = base.indexOf("."); dot !== -1; dot = base.indexOf(".", dot + 1)) {
    const id = ICON_BY_EXTENSION[base.slice(dot + 1)];
    if (id) return id;
  }
  return "file";
}

/** The icon for a file name or path. */
export function fileIcon(name: string): FileIcon {
  return ICONS[fileIconId(name)]!;
}
